local Window=getgenv().SORU_Window if not Window then return end
local MainAPI=Window:Tab({Title="Main"}) local MiscAPI=Window:Tab({Title="Misc"}) local EspAPI=Window:Tab({Title="Esp"}) local AnimalAPI=Window:Tab({Title="Animal"}) local EventAPI=Window:Tab({Title="Event"})
repeat task.wait() until Window.Tabs and Window.Tabs["Main"] and Window.Gui:FindFirstChild("Root")
local Players,TweenService,PPS,VIM,RS,Run=game:GetService("Players"),game:GetService("TweenService"),game:GetService("ProximityPromptService"),game:GetService("VirtualInputManager"),game:GetService("ReplicatedStorage"),game:GetService("RunService")
local plr=Players.LocalPlayer local V3,CF,C3=Vector3.new,CFrame.new,Color3.new
local function getScroll(n) local t=Window.Tabs[n] return t and t.frame and (t.frame:FindFirstChildOfClass("ScrollingFrame") or t.frame) end
local mainFrame,miscFrame,espFrame,animalFrame,eventFrame=getScroll("Main"),getScroll("Misc"),getScroll("Esp"),getScroll("Animal"),getScroll("Event")
repeat task.wait() until mainFrame and eventFrame
local function clear(f) for _,v in ipairs(f:GetChildren()) do if v:IsA("GuiObject") and not v:IsA("UIListLayout") and not v:IsA("UIPadding") then v:Destroy() end end end
for _,f in ipairs({mainFrame,miscFrame,espFrame,animalFrame,eventFrame}) do clear(f) end
local root=Window.Gui.Root
local SAFE, HELPER, OFF, RANGE, spd=V3(-75,3.5,-7.4), V3(-105.2,3.7,-6.2), 3, 15, 16
local ACC,DIM=Color3.fromRGB(139,92,246),Color3.fromRGB(148,140,180)
local function tw(o,p,t) return TweenService:Create(o,TweenInfo.new(t or .2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),p) end
local RScore={Common=1,Uncommon=2,Rare=3,Epic=4,Legendary=5,Mythic=6,Secret=7,Godly=8} local RCol={Common=Color3.fromRGB(180,180,180),Uncommon=Color3.fromRGB(92,255,92),Rare=Color3.fromRGB(85,170,255),Epic=Color3.fromRGB(170,85,255),Legendary=Color3.fromRGB(255,180,0),Mythic=Color3.fromRGB(255,60,60),Secret=Color3.fromRGB(0,0,0)}
local rf=RS:FindFirstChild("Rarities") local rarityNames={} if rf then for _,c in ipairs(rf:GetChildren()) do table.insert(rarityNames,c.Name) end else rarityNames={"Common","Rare","Epic","Legendary","Mythic","Secret"} end
local function getRarityScore(n) return RScore[n] or 0 end
local function getBase(m) if m.PrimaryPart then return m.PrimaryPart.Position end local ok,cf=pcall(function() return m:GetPivot() end) if ok then return V3(cf.X,cf.Y,cf.Z) end for _,v in ipairs(m:GetDescendants()) do if v:IsA("BasePart") then return v.Position end end end
local function getOff(m) local b=getBase(m) if not b then return end local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") local dir=hrp and V3(hrp.Position.X-b.X,0,hrp.Position.Z-b.Z) or V3(0,0,1) if dir.Magnitude<1 then dir=V3(0,0,1) end return V3(b.X,3.5,b.Z)+dir.Unit*OFF, V3(b.X,3.5,b.Z) end
local function getZB() local b=workspace:FindFirstChild("Build") if b then local zb=b:FindFirstChild("ZoneBuilds") if zb then return zb end end return workspace:FindFirstChild("ZoneBuilds") or workspace:FindFirstChild("Build") end
local function getZone(m) local p=getBase(m) if not p then return "Unknown" end local zb=getZB() if not zb then return "Unknown" end local c,mn="Unknown",1e9 for _,z in ipairs(zb:GetChildren()) do if z:IsA("Model") then local zp=getBase(z) if zp then local d=(V3(p.X,0,p.Z)-V3(zp.X,0,zp.Z)).Magnitude if d<mn then mn=d c=z.Name end end end end return c end
local function getCash(m) for _,v in ipairs(m:GetDescendants()) do if v.Name=="CashPerSecond" and v:IsA("TextLabel") then return v.Text end end return "?" end
local function parseCash(t) if not t then return 0 end local s=tostring(t):gsub("%$",""):gsub("/s",""):upper() local n=tonumber(s:match("[%d%.]+")) if not n then return 0 end if s:find("K") then n*=1e3 elseif s:find("M") then n*=1e6 elseif s:find("B") then n*=1e9 end return n end
local defend,atk,minCash,bigEgg="None",false,0,true local sel,selZone,selEgg={}, {}, nil local followTarg,followOn=nil,false local espOn,selEsp,espCache=false,{},{} local hallStay,hallOn,hallAct,lastClue,hasResetHall=3,false,false,0,false
local bloodOn,bloodAct,lastBlood,hasResetBlood=false,false,0,false -- NEW EVENT
local function getWS() return spd end
local function findDrop() for _,v in ipairs(plr.PlayerGui:GetDescendants()) do if v:IsA("TextButton") and (v.Name:lower():find("drop") or v.Text:lower():find("drop")) then return v end end end
local function isDropVis() local b=findDrop() if not b or not b.Visible then return false end local cur=b.Parent while cur and cur~=plr.PlayerGui do if cur:IsA("GuiObject") and not cur.Visible then return false end cur=cur.Parent end return true end
local function fireDrop() local b=findDrop() if b then pcall(function() b:Activate() end) end local r=RS:FindFirstChild("DropCarriedRemote",true) if r then pcall(function() r:FireServer() end) end end
local function closestPickup(md) local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local cl,mn=nil,md or 8 local fo=workspace:FindFirstChild("AnimalPickups") if not fo then return end for _,m in ipairs(fo:GetChildren()) do if m:IsA("Model") then local p=getBase(m) if p then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(p.X,0,p.Z)).Magnitude if d<mn then mn=d cl=m end end end end return cl end
local function isCarry(t) if not isDropVis() then return false end local c=closestPickup(8) if not c then return true end return c==t or c.Name==t.Name end
local function walkTo(pos,look,keep) local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp or not pos then return end local function left() return (V3(hrp.Position.X,0,hrp.Position.Z)-V3(pos.X,0,pos.Z)).Magnitude end if left()<1.2 then return end while left()>1.2 do if not hrp.Parent then break end local ws=getWS() local cur=V3(hrp.Position.X,pos.Y,hrp.Position.Z) local dir=V3(pos.X-cur.X,0,pos.Z-cur.Z) if dir.Magnitude<.1 then break end dir=dir.Unit local dt=Run.Heartbeat:Wait() local st=dir*ws*dt if st.Magnitude>left() then st=dir*left() end local np=cur+st hrp.CFrame=keep and CF(np)*(hrp.CFrame-hrp.CFrame.Position) or (look and CF(np,look) or CFrame.lookAt(np,np+dir)) hrp.AssemblyLinearVelocity=Vector3.zero end end
local function walkFB(pos,keep,orig) local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return false end local function left() return (V3(hrp.Position.X,0,hrp.Position.Z)-V3(pos.X,0,pos.Z)).Magnitude end if left()<1.2 then return true end while left()>1.2 do if not hrp.Parent then return false end if not isDropVis() then if orig and orig.Parent then local p=getOff(orig) if p then walkTo(p) end end return false end local cur=V3(hrp.Position.X,pos.Y,hrp.Position.Z) local dir=V3(pos.X-cur.X,0,pos.Z-cur.Z) if dir.Magnitude<.1 then break end dir=dir.Unit local dt=Run.Heartbeat:Wait() local st=dir*getWS()*dt if st.Magnitude>left() then st=dir*left() end local np=cur+st hrp.CFrame=keep and CF(np)*(hrp.CFrame-hrp.CFrame.Position) or CFrame.lookAt(np,np+dir) end return true end
local function walkDef(pos,mode,orig) if mode=="None" then return walkFB(pos,true,orig) end local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return false end local st=V3(hrp.Position.X,pos.Y,hrp.Position.Z) local dir=V3(pos.X-st.X,0,pos.Z-st.Z) if V3(dir.X,0,dir.Z).Magnitude<5 then return walkFB(pos,true,orig) end dir=V3(dir.X,0,dir.Z).Unit local perp=V3(-dir.Z,0,dir.X) local pts={} for i=1,4 do local t=i/5 local bp=st:Lerp(pos,t) pts[i]=bp+perp*(i%2==0 and 10 or -10) end for _,p in ipairs(pts) do if not walkFB(p,true,orig) then return false end task.wait(.05) end return walkFB(pos,true,orig) end
local function walkBaseF(orig) return walkDef(V3(-75,3.5,-7.4),defend,orig) and walkDef(SAFE,defend,orig) end
local function walkBase() walkTo(V3(-75,3.5,-7.4),nil,true) walkTo(SAFE,nil,true) end
local function makePrompt(p) if p:IsA("ProximityPrompt") then pcall(function() p.HoldDuration=0 p.MaxActivationDistance=RANGE p.RequiresLineOfSight=false end) end end
local function firePrompt(p) makePrompt(p) if fireproximityprompt then pcall(fireproximityprompt,p,0) end end
local function fireSteal(m) for _,v in ipairs(m:GetDescendants()) do if v:IsA("ProximityPrompt") then firePrompt(v) end end end
local function touchSteal(m) local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") local pr=m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart") if hrp and pr then pcall(function() firetouchinterest(hrp,pr,0) task.wait(.02) firetouchinterest(hrp,pr,1) end) end end
local function pressE() pcall(function() VIM:SendKeyEvent(true,Enum.KeyCode.E,false,game) task.wait(.05) VIM:SendKeyEvent(false,Enum.KeyCode.E,false,game) end) end
local stealMode="Normal" local function steal(m) if not m or not m.Parent then return end local tries=0 while tries<8 and m.Parent do if isDropVis() and not isCarry(m) then fireDrop() task.wait(.35) tries+=1 continue end if isDropVis() and isCarry(m) then break end local p,b=getOff(m) if p then walkTo(p,b) end touchSteal(m) fireSteal(m) pressE() task.wait(.25) tries+=1 end if not isDropVis() then walkBase() return end if not isCarry(m) then fireDrop() return end if stealMode=="Helper" then if not walkDef(HELPER,defend,m) then return end fireDrop() task.wait(.2) walkBaseF(m) else walkBaseF(m) end end

-- ESP
local function remEsp(m) local d=espCache[m] if d then pcall(function() d.hl:Destroy() end) pcall(function() d.bb:Destroy() end) espCache[m]=nil end end
local function clearEsp() for m in pairs(espCache) do remEsp(m) end end
local function addEsp(m) if espCache[m] or not m.Parent then return end local rar=m:GetAttribute("Rarity") or "?" if next(selEsp)~=nil and not selEsp[rar] then return end local ad=m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart") if not ad then return end local col=RCol[rar] or ACC local hl=Instance.new("Highlight",m) hl.Adornee=m hl.FillColor=col hl.OutlineColor=col hl.FillTransparency=.65 hl.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop local bb=Instance.new("BillboardGui",ad) bb.Adornee=ad bb.Size=UDim2.fromOffset(160,40) bb.StudsOffset=V3(0,4,0) bb.AlwaysOnTop=true local f=Instance.new("Frame",bb) f.Size=UDim2.new(1,0,1,0) f.BackgroundColor3=Color3.fromRGB(20,18,32) Instance.new("UICorner",f).CornerRadius=UDim.new(0,8) local t=Instance.new("TextLabel",f) t.Size=UDim2.new(1,-6,0,14) t.Position=UDim2.new(0,4,0,2) t.BackgroundTransparency=1 t.Text=m.Name:upper().." • "..string.upper(rar) t.Font=Enum.Font.GothamBold t.TextSize=9 t.TextColor3=C3(1,1,1) local s=Instance.new("TextLabel",f) s.Size=UDim2.new(1,-6,0,10) s.Position=UDim2.new(0,4,0,18) s.BackgroundTransparency=1 s.Text=getCash(m).." • "..getZone(m) s.Font=Enum.Font.GothamMedium s.TextSize=8 s.TextColor3=col espCache[m]={hl=hl,bb=bb} end
local function refreshEsp() if not espOn then clearEsp() return end local fo=workspace:FindFirstChild("AnimalPickups") if not fo then return end for _,m in ipairs(fo:GetChildren()) do if m:IsA("Model") then local rar=m:GetAttribute("Rarity") if next(selEsp)==nil or selEsp[rar] then addEsp(m) else remEsp(m) end end end end
local function closestClue() local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local cl,md=nil,1e9 for _,v in ipairs(workspace:GetDescendants()) do if v.Name=="DisguisedEggClue" then local p=getBase(v) if p then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(p.X,0,p.Z)).Magnitude if d<md then md=d cl=v end end end end if cl then return cl,getBase(cl) end end
local function closestBlood() local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local folder=workspace:FindFirstChild("BloodMoonPumpkinKings") if not folder then return end local cl,md,pos=nil,1e9,nil for _,v in ipairs(folder:GetDescendants()) do if v:IsA("Model") then local p=getBase(v) if p then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(p.X,0,p.Z)).Magnitude if d<md then md=d cl=v pos=p end end end end if cl then return cl,pos end local p=getBase(folder) if p then return folder,p end end
local function getEggSize(m) local v=m:GetAttribute("Size") or m:GetAttribute("EggSize") if type(v)=="number" then return v end local ok,_,s=pcall(function() return m:GetBoundingBox() end) if ok and s then return s.Magnitude end return 0 end
local function getEggs(zone) local zb=getZB() if not zb then return {} end local zm=zb:FindFirstChild(zone) if not zm then return {} end local er=zm:FindFirstChild("Eggs") or zm local out={} for _,v in ipairs(er:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end if bigEgg then table.sort(out,function(a,b) return getEggSize(a)>getEggSize(b) end) end return out end
local function equipPick() local ch=plr.Character if not ch then return end local t=ch:FindFirstChildOfClass("Tool") if t and t.Name:lower():find("pick") then return t end for _,v in ipairs(plr.Backpack:GetChildren()) do if v:IsA("Tool") then v.Parent=ch return v end end end
workspace.DescendantAdded:Connect(function(v) if v:IsA("ProximityPrompt") then task.wait(.1) makePrompt(v) end end)
for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("ProximityPrompt") then makePrompt(v) end end
local zoneNames={} local zb=getZB() if zb then for _,m in ipairs(zb:GetChildren()) do if m:IsA("Model") then table.insert(zoneNames,m.Name) end end end if #zoneNames==0 then zoneNames={"Zone1"} end

