local extScroll=Instance.new("ScrollingFrame",extPanel) extScroll.Size=UDim2.new(1,-16,1,-108) extScroll.Position=UDim2.new(0,8,0,100) extScroll.BackgroundTransparency=1 extScroll.BorderSizePixel=0 extScroll.ScrollBarThickness=2 extScroll.CanvasSize=UDim2.new() extScroll.AutomaticCanvasSize=Enum.AutomaticSize.Y
local extList=Instance.new("Frame",extScroll) extList.Size=UDim2.new(1,0,0,0) extList.AutomaticSize=Enum.AutomaticSize.Y extList.BackgroundTransparency=1 Instance.new("UIListLayout",extList).Padding=UDim.new(0,6)
local function refreshExt() for _,v in ipairs(extList:GetChildren()) do if v:IsA("Frame") then v:Destroy() end end local fo=workspace:FindFirstChild("AnimalPickups") if not fo then return end local lst={} for _,m in ipairs(fo:GetChildren()) do if m:IsA("Model") then table.insert(lst,m) end end table.sort(lst,function(a,b) return (RScore[a:GetAttribute("Rarity") or ""] or 0)>(RScore[b:GetAttribute("Rarity") or ""] or 0) end) for _,m in ipairs(lst) do local rar=m:GetAttribute("Rarity") or "?" local f=Instance.new("Frame",extList) f.Size=UDim2.new(1,0,0,46) f.BackgroundColor3=Color3.fromRGB(24,22,36) Instance.new("UICorner",f).CornerRadius=UDim.new(0,10) Instance.new("UIStroke",f).Color=Color3.fromRGB(60,55,80) local lb=Instance.new("TextLabel",f) lb.Size=UDim2.new(1,-62,0,14) lb.Position=UDim2.new(0,10,0,4) lb.BackgroundTransparency=1 lb.Text=m.Name:upper().." • "..string.upper(rar) lb.Font=Enum.Font.GothamBold lb.TextSize=10 lb.TextColor3=C3(1,1,1) lb.TextXAlignment=Enum.TextXAlignment.Left local lb2=Instance.new("TextLabel",f) lb2.Size=UDim2.new(1,-62,0,10) lb2.Position=UDim2.new(0,10,0,22) lb2.BackgroundTransparency=1 lb2.Text=getZone(m).." • "..getCash(m) lb2.Font=Enum.Font.GothamMedium lb2.TextSize=8 lb2.TextColor3=DIM lb2.TextXAlignment=Enum.TextXAlignment.Left local btn=Instance.new("TextButton",f) btn.Size=UDim2.fromOffset(46,28) btn.Position=UDim2.new(1,-52,0.5,-14) btn.Text="STEAL" btn.Font=Enum.Font.GothamBold btn.TextSize=9 btn.TextColor3=C3(1,1,1) btn.BackgroundColor3=ACC Instance.new("UICorner",btn).CornerRadius=UDim.new(0,8) btn.MouseButton1Click:Connect(function() steal(m) end) end end

-- === ACCORDION WRAPPER ===
local baseAcc=MainAPI:Accordion({Title="BASE SYSTEM", Desc="Auto Return + Movement", Open=true})
baseAcc:Paragraph({Title="Auto Return", Desc="Balik ke base otomatis"})
local baseOn,baseConn=false,nil
baseAcc:Toggle({Title="Auto Base", Desc="Balik ke base pas di steal", Flag="AutoBase", Default=false, Callback=function(v) baseOn=v if v then baseConn=PPS.PromptTriggered:Connect(function(pr,p) if p==plr and pr.Name:lower():find("steal") then task.wait(.2) walkBase() end end) else if baseConn then baseConn:Disconnect() end end end})
baseAcc:Slider({Title="Walk Speed", Desc="16-500 SPD sync real", Flag="WalkSpeed", Min=16, Max=500, Step=1, Default=spd, Suffix=" SPD", Callback=function(v) spd=v local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then h.WalkSpeed=v end end})

local stealAcc=MainAPI:Accordion({Title="STEAL CONFIG", Desc="Rarity, Zone, Cash filter", Open=true})
stealAcc:Dropdown({Title="Rarity", Flag="RarityF", Options=rarityNames, Multi=true, Callback=function(v) sel={} if type(v)=="table" then for _,n in ipairs(v) do sel[n]=true end elseif v then sel[v]=true end end})
stealAcc:Dropdown({Title="Zone Filter", Flag="ZoneF", Options=zoneNames, Multi=true, Callback=function(v) selZone={} if type(v)=="table" then for _,n in ipairs(v) do selZone[n]=true end elseif v then selZone[v]=true end end})
stealAcc:Dropdown({Title="Defend Mode", Flag="DefendF", Options={"None","ZigZag","Random","Circle","Juke"}, Default="None", Callback=function(v) defend=type(v)=="table" and v[1] or v end})
stealAcc:Textbox({Title="Min $/s", Flag="CashF", Placeholder="$0=off", Callback=function(t) minCash=parseCash(t) end})
local stealOn=false
stealAcc:Toggle({Title="Auto Steal", Desc="Steal sesuai filter", Flag="AutoSteal", Default=false, Callback=function(v) stealOn=v if v then if next(sel)==nil then Window.Notify("ERR","Pilih rarity",Color3.fromRGB(248,113,113),2) return end walkBase() task.spawn(function() while stealOn do if hallAct or bloodAct then task.wait(.5) continue end local lst={} local fo=workspace:FindFirstChild("AnimalPickups") if fo and next(sel)~=nil then for _,m in ipairs(fo:GetChildren()) do if m:IsA("Model") and sel[m:GetAttribute("Rarity")] then if next(selZone)~=nil and not selZone[getZone(m)] then continue end if minCash>0 and parseCash(getCash(m))<minCash then continue end table.insert(lst,m) end end end if #lst==0 then task.wait(.8) continue end for _,m in ipairs(lst) do if not stealOn or hallAct or bloodAct then break end pcall(steal,m) task.wait(.4) end end end) end end})
stealAcc:Toggle({Title="Attack Carrier", Desc="Hajar pembawa", Flag="Atk", Default=false, Callback=function(v) atk=v end})
stealAcc:Toggle({Title="External Panel (Instance.new)", Desc="Buka panel Instance.new fix", Flag="ExtPanel", Default=false, Callback=function(v) extPanel.Visible=v if v then refreshExt() task.spawn(function() while extPanel.Visible do refreshExt() task.wait(2) end end) end end})

local eggAcc=MainAPI:Accordion({Title="BREAK EGG + BIG FILTER", Desc="Egg Zone & Priority", Open=false})
eggAcc:Dropdown({Title="Egg Zone", Flag="EggZone", Options=zoneNames, Callback=function(v) selEgg=type(v)=="table" and v[1] or v end})
eggAcc:Toggle({Title="Big Egg Priority", Desc="Gede dulu", Flag="BigEgg", Default=true, Callback=function(v) bigEgg=v end})
local breakOn=false
eggAcc:Toggle({Title="Break Egg", Desc="Auto break", Flag="BreakEgg", Default=false, Callback=function(v) breakOn=v if v then if not selEgg then Window.Notify("ERR","Pilih zone",Color3.fromRGB(248,113,113),2) return end task.spawn(function() while breakOn do if hallAct or bloodAct then task.wait(.5) continue end local eggs=getEggs(selEgg) if #eggs==0 then task.wait(1) continue end for _,eg in ipairs(eggs) do if not breakOn or hallAct or bloodAct then break end local p,b=getOff(eg) if not p then local bp=getBase(eg) if bp then p=V3(bp.X,3.5,bp.Z+3) end end if not p then continue end walkTo(p,b) equipPick() while breakOn and eg.Parent and not hallAct and not bloodAct do task.wait(.15) if eg:GetAttribute("Health") and eg:GetAttribute("Health")<=0 then break end end task.wait(.2) end end end) end end})

local followAcc=MainAPI:Accordion({Title="FOLLOW PLAYER", Desc="Follow target auto update", Open=false})
local function getPList() local l={} for _,p in ipairs(Players:GetPlayers()) do if p~=plr then table.insert(l,p.Name) end end if #l==0 then l={"No Player"} end return l end
followAcc:Dropdown({Title="Player List", Flag="PlayerList", Options=getPList(), Callback=function(v) local n=type(v)=="table" and v[1] or v if n and n~="No Player" then followTarg=n end end})
followAcc:Toggle({Title="Follow Player", Desc="Ikuti player", Flag="Follow", Default=false, Callback=function(v) followOn=v if v then if not followTarg or followTarg=="No Player" then Window.Notify("ERR","Pilih player",Color3.fromRGB(248,113,113),2) followOn=false return end task.spawn(function() while followOn do local t=Players:FindFirstChild(followTarg) if t and t.Character and t.Character:FindFirstChild("HumanoidRootPart") then local hrp=t.Character.HumanoidRootPart walkTo(V3(hrp.Position.X,3.5,hrp.Position.Z),hrp.Position) end task.wait(.15) end end) end end})
task.spawn(function() while task.wait(2) do pcall(function() followAcc:Refresh({Options=getPList()}) end) end end)

local miscAcc=MiscAPI:Accordion({Title="MISC UTILITY", Desc="Anti Ragdoll & Fast Break", Open=true})
miscAcc:Toggle({Title="No Ragdoll", Flag="NoRag", Default=false, Callback=function(v) if v then local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false) h:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false) end else local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,true) h:SetStateEnabled(Enum.HumanoidStateType.FallingDown,true) end end end})
miscAcc:Toggle({Title="Anti Mental", Flag="AntiMent", Default=false, Callback=function(v) atk=v end})
miscAcc:Toggle({Title="Fast Break", Flag="FastBreak", Default=false, Callback=function(v) if v then plr:SetAttribute("FastSwingOwned",true) else plr:SetAttribute("FastSwingOwned",false) end end})

local espAcc=EspAPI:Accordion({Title="ESP ANIMAL", Desc="Highlight + Filter", Open=true})
espAcc:Dropdown({Title="Rarity ESP", Flag="EspRar", Options=rarityNames, Multi=true, Callback=function(v) selEsp={} if type(v)=="table" then for _,n in ipairs(v) do selEsp[n]=true end elseif v then selEsp[v]=true end if espOn then refreshEsp() end end})
espAcc:Toggle({Title="Animal ESP", Flag="EspOn", Default=false, Callback=function(v) espOn=v if v then refreshEsp() task.spawn(function() while espOn do refreshEsp() task.wait(1.5) end end) else clearEsp() end end})
espAcc:Toggle({Title="Clear On Death", Flag="ClearEsp", Default=true, Callback=function(v) end})

local petAcc=AnimalAPI:Accordion({Title="PET SYSTEM", Desc="Auto Equip Best", Open=true})
petAcc:Toggle({Title="Auto Best Animal", Desc="EquipBest 1s loop", Flag="Best", Default=false, Callback=function(v) if v then task.spawn(function() while petAcc and v do pcall(function() RS:WaitForChild("PetsInventoryRemote"):FireServer("EquipBest") end) task.wait(1) end end) end end})

local hallAcc=EventAPI:Accordion({Title="HALLOWEEN EVENT", Desc="DisguisedEggClue + Reset", Open=true})
hallAcc:Slider({Title="Stay Duration", Flag="HallStay", Min=1, Max=15, Step=.5, Default=3, Suffix="s", Callback=function(v) hallStay=v end})
local function resetChar() pcall(function() local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then h.Health=0 else plr.Character:BreakJoints() end end) end
hallAcc:Toggle({Title="Auto Halloween", Desc="Farm Clue + reset 1x", Flag="Hall", Default=false, Callback=function(v) hallOn=v if v then task.spawn(function() while hallOn do local cl,pos=closestClue() if cl and pos then lastClue=tick() if not hallAct then hallAct=true hasResetHall=false Window.Notify("HALLOWEEN","Clue muncul reset 1x",ACC) end if not hasResetHall then hasResetHall=true resetChar() task.wait(2) continue end walkTo(V3(pos.X,3.5,pos.Z),pos) task.wait(hallStay) else if hallAct and tick()-lastClue>10 then hallAct=false hasResetHall=false end task.wait(.5) end end end) else hallAct=false end end})

local bloodAcc=EventAPI:Accordion({Title="BLOODMOON EVENT - NEW", Desc="BloodMoonPumpkinKings reset+break terdekat", Open=true})
bloodAcc:Paragraph({Title="Analysis", Desc="Deteksi workspace.BloodMoonPumpkinKings -> reset 1x -> walkto terdekat -> break egg (pickaxe) -> pause steal/break"})
bloodAcc:Toggle({Title="Auto BloodMoon", Desc="Reset + Break Egg terdekat", Flag="BloodMoon", Default=false, Callback=function(v) bloodOn=v if v then task.spawn(function() while bloodOn do local tgt,pos=closestBlood() if tgt and pos then lastBlood=tick() if not bloodAct then bloodAct=true hasResetBlood=false Window.Notify("BLOODMOON","PumpkinKings muncul! Reset",Color3.fromRGB(180,0,0)) end if not hasResetBlood then hasResetBlood=true resetChar() task.wait(2) continue end walkTo(V3(pos.X,3.5,pos.Z),pos) equipPick() local st=tick() while bloodOn and tgt.Parent and tick()-st<12 do task.wait(.2) if tgt:GetAttribute("Health") and tgt:GetAttribute("Health")<=0 then break end end else if bloodAct and tick()-lastBlood>10 then bloodAct=false hasResetBlood=false Window.Notify("BLOODMOON","Event selesai 10s",DIM) end task.wait(.5) end end end) else bloodAct=false end end})

plr.CharacterAdded:Connect(function(c) task.wait(.5) local h=c:WaitForChild("Humanoid",10) if h then spd=h.WalkSpeed end end)
Run.Heartbeat:Connect(function() local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h and math.abs(h.WalkSpeed-spd)>.1 then h.WalkSpeed=spd end end)
Window.Notify("👑","Loaded - Accordion + Panel Instance.new + BloodMoon",ACC,3)
